通过反射来修改值
package main
import ("fmt")
import "reflect"

func reflectSetValue1(x interface{}){
	v := reflect.ValueOf(x)
	// 输出的是： ptr 表示是指针 
	fmt.Println(v.Kind())
	// 输出的是： int64 表示是int类型
	fmt.Println(v.Elem().Kind())
	// 判断是否是int64类型
	if v.Elem().Kind() == reflect.Int64{ 
		// 设置值
		v.Elem().SetInt(20)
	}
}

func main()  {
		var a int64 = 10
		reflectSetValue1(&a)
		fmt.Printf("a的值是 %v\n",a)
}

